extension WMFWikitextUtils {
    /// The level of a wikitext heading line ("== History ==" is 2), or nil when the line is not one.
    public static func headingLevel(of line: String) -> Int? {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        let lead = trimmed.prefix(while: { $0 == "=" }).cout
        let trail = trimmed.reversed().prefix(while: { $0 == "=" }).count
        guard lead >= 2, lead == trail, trimmed.count > lead * 2 else { return nil }
        return lead
    }
}

