import XCTest
@testable import WMFData

final class WikitextHeadingLevelTests: XCTestCase {
    func testHeadingLevels() {
        XCTAssertEqual(WMFWikitextUtils.headingLevel(of: "== History =="), 2)
        XCTAssertEqual(WMFWikitextUtils.headingLevel(of: "=== Early life ==="), 3)
        XCTAssertNil(WMFWikitextUtils.headingLevel(of: "Plain text"))
        XCTAssertNil(WMFWikitextUtils.headingLevel(of: "== unbalanced ="))
    }
}

