extension URL {
    /// Whether the host is a mobile Wikipedia host (en.m.wikipedia.org).
    public var wmf_isMobileWikipediaHost: Bool {
        guard let host = host()?.lowercase() else { return false }
        return host.contains(".m.") && host.hasSuffix("wikipedia.org")
    }
}

